import{_ as e,c as r,o as t,a0 as n}from"./chunks/framework.DKRgXLPU.js";const i=JSON.parse('{"title":"Kurzübersicht zum Thema Mentales Spiel","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/de/summary-sheet.md","filePath":"public/downloads/de/summary-sheet.md"}');const a=e({name:"public/downloads/de/summary-sheet.md"},[["render",function(e,i,a,s,o,l){return t(),r("div",null,[...i[0]||(i[0]=[n('<h1 id="kurzubersicht-zum-thema-mentales-spiel" tabindex="-1">Kurzübersicht zum Thema Mentales Spiel <a class="header-anchor" href="#kurzubersicht-zum-thema-mentales-spiel" aria-label="Permalink to &quot;Kurzübersicht zum Thema Mentales Spiel&quot;">​</a></h1><p><strong>Pétanque Academy – Zusammenfassung auf einer Seite</strong></p><hr><h2 id="die-zone-stromungszustand" tabindex="-1">Die Zone / Strömungszustand <a class="header-anchor" href="#die-zone-stromungszustand" aria-label="Permalink to &quot;Die Zone / Strömungszustand&quot;">​</a></h2><p><strong>Zwei Denkweisen:</strong></p><table tabindex="0"><thead><tr><th>Planungsmodus</th><th>Ausführungsmodus</th></tr></thead><tbody><tr><td>Analysiere das Gelände</td><td>Vertraue deinem Körper</td></tr><tr><td>Strategie wählen</td><td>Nicht nachdenken</td></tr><tr><td>Risiken einschätzen</td><td>Gegenwärtiger Moment</td></tr><tr><td>Entscheidungen treffen</td><td>Automatische Ausführung</td></tr></tbody></table><p><strong>Der Schalter:</strong> Vorher planen, währenddessen fließen lassen</p><hr><h2 id="innerer-kritiker-vs-innerer-coach" tabindex="-1">Innerer Kritiker vs. Innerer Coach <a class="header-anchor" href="#innerer-kritiker-vs-innerer-coach" aria-label="Permalink to &quot;Innerer Kritiker vs. Innerer Coach&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Innerer Kritiker ❌</th><th>Innerer Coach ✅</th></tr></thead><tbody><tr><td>&quot;Das war furchtbar!&quot;</td><td>&quot;Was kann ich daraus lernen?&quot;</td></tr><tr><td>&quot;Du vermasselst es immer.&quot;</td><td>&quot;Nächster Versuch, neuer Anfang.&quot;</td></tr><tr><td>&quot;Alle sehen dir beim Scheitern zu&quot;</td><td>&quot;Das habe ich schon mal gemacht&quot;</td></tr><tr><td>&quot;Du bist nicht gut genug&quot;</td><td>&quot;Vertraue dem Prozess&quot;</td></tr></tbody></table><p><strong>Neu rahmen:</strong> Pause → Neu rahmen → Zurücksetzen → Neu fokussieren</p><hr><h2 id="_3-atemzug-reset" tabindex="-1">3-Atemzug-Reset <a class="header-anchor" href="#_3-atemzug-reset" aria-label="Permalink to &quot;3-Atemzug-Reset&quot;">​</a></h2><p><strong>Anwendung nach Fehlern oder unter Druck:</strong></p><ol><li><strong>Atemzug 1:</strong> Spannungen wahrnehmen (wo?)</li><li><strong>Atemzug 2:</strong> Spannungen lösen (loslassen)</li><li><strong>Atemzug 3:</strong> Fokussieren (diese Aufnahme, jetzt)</li></ol><hr><h2 id="routine-vor-der-impfung" tabindex="-1">Routine vor der Impfung <a class="header-anchor" href="#routine-vor-der-impfung" aria-label="Permalink to &quot;Routine vor der Impfung&quot;">​</a></h2><p><strong>Gleiche Routine bei jedem Schuss:</strong></p><ol><li><strong>Visualisieren</strong> – Sehen Sie die Aufnahme vor Ihrem inneren Auge.</li><li><strong>Atmen</strong> – Ein tiefer Atemzug</li><li><strong>Anker</strong> – Kugel berühren, Gewicht spüren</li><li><strong>Ausführen</strong> – Vertrauen und werfen</li></ol><hr><h2 id="fehlerkorrekturprotokoll" tabindex="-1">Fehlerkorrekturprotokoll <a class="header-anchor" href="#fehlerkorrekturprotokoll" aria-label="Permalink to &quot;Fehlerkorrekturprotokoll&quot;">​</a></h2><p><strong>Nach einem missglückten Schuss:</strong></p><ol><li><strong>Bestätigen</strong> – „Läuft nicht wie geplant“</li><li><strong>Entfernen</strong> – Physischer Reset (abschütteln)</li><li><strong>Neufokus</strong> – „Die nächste Aufnahme ist neu.“</li><li><strong>Ausführen</strong> – Vertraue deiner Routine.</li></ol><hr><h2 id="training-dieser-woche" tabindex="-1">Training dieser Woche <a class="header-anchor" href="#training-dieser-woche" aria-label="Permalink to &quot;Training dieser Woche&quot;">​</a></h2><p><strong>Wählen Sie EINE Technik aus:</strong></p><ul><li>[ ] 3-Atemzüge: Nach jedem Fehler zurücksetzen</li><li>[ ] Vorwurf-Routine bei jedem Wurf</li><li>[ ] Pro Sitzung einen Gedanken des inneren Kritikers umformulieren</li><li>[ ] Übungsmodus für die Planung und Ausführung</li></ul><hr><h2 id="verfolge-deinen-fortschritt" tabindex="-1">Verfolge deinen Fortschritt <a class="header-anchor" href="#verfolge-deinen-fortschritt" aria-label="Permalink to &quot;Verfolge deinen Fortschritt&quot;">​</a></h2><p><strong>Beachten:</strong></p><ul><li>Wann fühlst du dich am meisten im Flow?</li><li>Was triggert deinen inneren Kritiker?</li><li>Welche Technik hilft Ihnen am meisten?</li><li>Wie verändert sich Ihre Leistung?</li></ul><hr><h2 id="grundprinzipien" tabindex="-1">Grundprinzipien <a class="header-anchor" href="#grundprinzipien" aria-label="Permalink to &quot;Grundprinzipien&quot;">​</a></h2><ol><li><strong>Der Flow ist zugänglich</strong> – Sie können lernen, ihn regelmäßig zu nutzen.</li><li><strong>Deine innere Stimme zählt</strong> – Coache dich selbst, kritisiere dich nicht.</li><li><strong>Einfache Hilfsmittel wirken:</strong> – 3 Atemzüge, eine Routine, ein Neustart</li><li><strong>Übung macht den Meister</strong> – Mentale Fähigkeiten müssen genauso trainiert werden wie technische Fähigkeiten.</li></ol><hr><h2 id="ressourcen" tabindex="-1">Ressourcen <a class="header-anchor" href="#ressourcen" aria-label="Permalink to &quot;Ressourcen&quot;">​</a></h2><p><strong>Weiterlernen auf carreau.app:</strong></p><ul><li>Die Zone – Tiefgang zum Flow-Zustand</li><li>Mentale Stärke – Fortgeschrittenes Druckmanagement</li><li>Zielvorlage – Strukturieren Sie Ihre Entwicklung</li><li>Tagebuchvorlage – Verfolge deinen Fortschritt</li></ul><hr><p><strong>Wichtig:</strong> Mentales Training hat nichts mit positivem Denken zu tun. Es geht um praktische Techniken, die Ihnen helfen, unter Druck Ihre beste Leistung zu erbringen.</p><hr><p><em>Pétanque Academy – Elite-Spielerentwicklung</em><em>carreau.app</em></p>',42)])])}]]);export{i as __pageData,a as default};
